const ticker = String($json.body?.ticker ?? $json.ticker ?? 'AAPL').trim().toUpperCase();
if (!/^[A-Z0-9.^=-]{1,15}$/.test(ticker)) throw new Error('Invalid ticker');
return [{json:{ticker}}];

const r = $json.chart?.result?.[0];
if (!r?.indicators?.quote?.[0]?.close) throw new Error('No historical prices returned');
const c = r.indicators.quote[0].close.filter(Number.isFinite);
if (c.length < 2) throw new Error('Not enough daily history');
const previousDayBullish = c[c.length - 1] >= c[c.length - 2];
return [{json:{ticker:$('Normalize ticker1').first().json.ticker, optionType:previousDayBullish?'C':'P', previousDayBullish}}];

const ticker = $('Normalize ticker1').first().json.ticker;
const userAgent = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36';

const fc = await this.helpers.httpRequest({
  method: 'GET',
  url: 'https://fc.yahoo.com/',
  headers: { 'User-Agent': userAgent, 'Accept': '*/*' },
  returnResponse: true,
  ignoreHttpStatusErrors: true,
});
const headers = fc.headers || {};
const headerDebug = Object.keys(headers).join(',').slice(0, 200);
const rawSetCookie = headers['set-cookie'] ?? headers['Set-Cookie'] ?? headers['SET-COOKIE'];
let cookieString = '';
if (Array.isArray(rawSetCookie)) {
  cookieString = rawSetCookie.map(c => c.split(';')[0]).join('; ');
} else if (typeof rawSetCookie === 'string' && rawSetCookie) {
  cookieString = rawSetCookie.split(';')[0];
}
if (!cookieString) throw new Error('No Set-Cookie. HeaderKeys: ' + headerDebug + ' | BodyHead: ' + String(fc.body).slice(0, 100));

const crumbRes = await this.helpers.httpRequest({
  method: 'GET',
  url: 'https://query1.finance.yahoo.com/v1/test/getcrumb',
  headers: { 'User-Agent': userAgent, 'Cookie': cookieString, 'Accept': '*/*' },
  returnResponse: true,
  ignoreHttpStatusErrors: true,
});
const crumb = String(crumbRes.body || '').trim();
if (!crumb || crumb.length < 5) throw new Error('Failed to obtain valid crumb (status: ' + crumbRes.statusCode + ', body: ' + String(crumbRes.body).slice(0,80) + ')');

const chainRes = await this.helpers.httpRequest({
  method: 'GET',
  url: 'https://query1.finance.yahoo.com/v7/finance/options/' + ticker + '?crumb=' + encodeURIComponent(crumb),
  headers: { 'User-Agent': userAgent, 'Cookie': cookieString, 'Accept': '*/*' },
  returnResponse: true,
  ignoreHttpStatusErrors: true,
});
const body = typeof chainRes.body === 'string' ? JSON.parse(chainRes.body) : chainRes.body;
if (!body?.optionChain?.result?.[0]) throw new Error('Yahoo options API returned no result for ' + ticker + ' (status: ' + chainRes.statusCode + ', body: ' + JSON.stringify(body).slice(0,200) + ')');

return [{ json: { ticker, crumb, body, source: 'yahoo-v7', cookieUsed: cookieString.slice(0, 60) + '...' } }];

const base = $('Choose calls or puts1').first().json;
const yahoo = $('Fetch Yahoo Options Chain (with session)').first().json;
const chain = yahoo?.body?.optionChain?.result?.[0];
if (!chain) throw new Error('Yahoo options API returned no result');
const type = base.optionType;
const lists = [chain.options?.[0]];
if (chain.options?.[1]) lists.push(chain.options[1]);
const all = lists.filter(Boolean).flatMap(b => (b[type === 'C' ? 'calls' : 'puts'] || []));
const eligible = all.filter(c => Number.isFinite(c.ask) && c.ask >= 20 && c.ask <= 600 && (!c.inTheMoney));
if (eligible.length < 10) throw new Error('Only ' + eligible.length + ' eligible contracts from Yahoo API');
eligible.sort((a,b) => a.ask-b.ask);
const picked = [];
for (let i=0;i<10;i++) picked.push(eligible[Math.round(i*(eligible.length-1)/9)]);
return picked.map(c => ({json:{...base, symbol:c.contractSymbol, contractType:type, strike:c.strike, expiration:c.expiration, ask:c.ask, daysRangeLow:c.dayLow, daysRangeTop:c.dayHigh}}));

const rows = $input.all().map(x=>x.json);
const enriched = rows.map(r => {
  const low = Number(r.daysRangeLow), high = Number(r.daysRangeTop);
  const ok = Number.isFinite(low) && Number.isFinite(high) && low > 0 && high >= low;
  return {...r, rangePct: ok ? (high-low)/low*100 : null, eligible: ok};
});
const good = enriched.filter(r => r.eligible && Number.isFinite(r.rangePct));
if (!good.length) throw new Error('No contract returned a usable day range');
good.sort((a,b)=>b.rangePct-a.rangePct);
const winners = good.slice(0, Math.min(3, good.length));
const round5 = n => Math.round(n/5)*5;
return [{json:{ticker:rows[0].ticker, optionType:rows[0].optionType, previousDayBullish:rows[0].previousDayBullish, idealPriceRange:{min:round5(Math.min(...winners.map(x=>x.ask))),max:round5(Math.max(...winners.map(x=>x.ask)))}, selectedContracts:winners, allAnalyzed:enriched.sort((a,b)=>(b.rangePct??-1)-(a.rangePct??-1))}}];
